D=$(mktemp -d); echo "" | base64 -d > $D/amb.py; echo "" | base64 -d > $D/pos.py
for i in $(seq 1 6); do sudo podman exec faceops test -f /opt/faceops/app/mapa_posiciones.py 2>/dev/null && break; sleep 30; done
sudo podman exec faceops cat /opt/faceops/app/version.json 2>/dev/null | head -c 200; echo
curl -sk -o /dev/null -w "lab http %{http_code}\n" https://faceops.34.176.42.56.sslip.io:8843/faceops/ || true
sudo podman exec -i -e FACEOPS_VIGIA=0 faceops python3 - < $D/amb.py 2>&1 | grep -E "^RESULTADO|App de pagos \| desarrollo .*data lake|falla|Traceback" | head -20
sudo podman exec -i -e FACEOPS_VIGIA=0 faceops python3 - < $D/pos.py 2>&1 | grep -E "^POS|^PAGINA|Traceback"
